/* Türkisch A2 – Rollenspiel-Dialoge für Deutschsprechende (Erklärungen, Übersetzungen und Fragen auf Deutsch)
 * Format: siehe js/content/tr-a1-dialogs.js und Wahlzeilen (me:true) wie in tools/fixtures/roleplay-test.js.
 * IDs: Dialog tr-a2-dNN, Wahlzeilen <id>.c1…, Fragen <id>.1… – NIE ändern oder wiederverwenden.
 */
(function (K) {

K.addDialog('tr-a2-d01', {
  level: 'A2', scene: 'hastane', title: 'Eczanede', sub: 'In der Apotheke: Rezept einlösen und Beschwerden schildern',
  role: 'Kundin', roleG: 'f',
  lines: [
    { s: "Eczacı", g: "m", t: "Merhaba, hoş geldiniz. Nasıl yardımcı olabilirim?", n: "Guten Tag, willkommen. Wie kann ich Ihnen helfen?" },
    { me: true, id: "tr-a2-d01.c1",
      o: ["Merhaba. Dün doktora gittim, bu reçeteyi verdi. İlaçlarımı alabilir miyim?", "Merhaba. Reçete bu, ilaçları ver bana.", "Merhaba. Dün doktora gitti, bu reçeteyi verdi."], a: 0,
      why: { 1: "„ver bana“ ist ein knapper Befehl. In der Apotheke bittest du höflich: „… alabilir miyim?“ (Kann ich … bekommen?).", 2: "„gitti“ heißt „er/sie ging“. Du sprichst von dir selbst, also „gittim“ (ich ging). Außerdem fehlt die eigentliche Bitte." },
      e: "Erst kurz erzählen (-dI-Vergangenheit: „gittim“), dann höflich bitten mit „-(y)Abilir miyim?“ – das klingt in Geschäften immer freundlich.",
      n: "Guten Tag. Ich war gestern beim Arzt, er hat mir dieses Rezept gegeben. Kann ich meine Medikamente bekommen?" },
    { s: "Eczacı", g: "m", t: "Tabii, bir bakayım. Öksürük şurubu ve ağrı kesici yazmış. Başka bir şikâyetiniz var mı?", n: "Natürlich, ich schaue mal. Hustensaft und ein Schmerzmittel sind verschrieben. Haben Sie noch andere Beschwerden?" },
    { me: true, id: "tr-a2-d01.c2",
      o: ["Evet, iki gündür boğazım ağrıyor ve biraz ateşim var.", "Evet, iki gün boğaz ağrıyor ve ateş var.", "Evet, iki gündür boğazım ağrıyorum."], a: 0,
      why: { 1: "Verständlich, aber ohne Possessivendung klingt es wie ein Telegramm. Auf Türkisch gehört der Körperteil zu dir: „boğazım“, „ateşim“. Außerdem fehlt „-dür“ für „seit“.", 2: "Bei „ağrımak“ ist der Körperteil das Subjekt: „boğazım ağrıyor“ (mein Hals schmerzt). Mit „ağrıyorum“ würdest du sagen, dass **du selbst** wehtust." },
      e: "Beschwerden: Körperteil + Possessiv + „ağrıyor“ („başım ağrıyor“) bzw. „… var“ („ateşim var“). „iki gündür“ = seit zwei Tagen.",
      n: "Ja, seit zwei Tagen tut mir der Hals weh, und ich habe etwas Fieber." },
    { s: "Eczacı", g: "m", t: "Anladım. Şurubu günde üç kez, yemeklerden sonra kullanın. Ağrı kesiciyi aç karnına almayın.", n: "Verstanden. Nehmen Sie den Saft dreimal täglich nach den Mahlzeiten. Nehmen Sie das Schmerzmittel nicht auf nüchternen Magen." },
    { me: true, id: "tr-a2-d01.c3",
      o: ["Pardon, ağrı kesiciyi günde kaç kez alabilirim?", "Pardon, ağrı kesiciyi günde kaç kez alabilirsin?", "Pardon, ağrı kesiciyi günde kaç kez alamam?"], a: 0,
      why: { 1: "„alabilirsin“ heißt „du kannst nehmen“. Du fragst aber, was **du** darfst, und das ist „alabilirim“ (ich kann/darf nehmen). Außerdem wäre „sen“ gegenüber dem Apotheker zu vertraut.", 2: "„alamam“ ist verneint: „ich kann nicht nehmen“. Gefragt wird aber „wie oft darf ich nehmen?“ – also bejaht: „alabilirim“." },
      e: "Möglichkeit/Erlaubnis: Verbstamm + **-(y)Abil** + Personenendung. „almak“ → „alabilirim“ (ich kann/darf nehmen). Verneint wird es „-(y)AmA-“: „alamam“.",
      n: "Entschuldigung, wie oft am Tag darf ich das Schmerzmittel nehmen?" },
    { s: "Eczacı", g: "m", t: "Günde iki kez yeterli. Bir şeyler yedikten sonra alın ve bol su için. Bir de evde dinlenin.", n: "Zweimal am Tag reicht. Nehmen Sie es nach dem Essen und trinken Sie viel Wasser. Und ruhen Sie sich zu Hause aus." },
    { me: true, id: "tr-a2-d01.c4",
      o: ["Çok teşekkür ederim. Hoşça kalın!", "Çok teşekkür ederim. Hoşça kal!", "Çok teşekkür ederim. Güle güle!"], a: 0,
      why: { 1: "„Hoşça kal“ ist die Form für „du“. Zu einem Apotheker, den du nicht kennst, passt „siz“: „Hoşça kalın“.", 2: "„Güle güle“ sagt der, der **bleibt**, zu dem, der geht. Wenn du selbst gehst, sagst du „Hoşça kalın“." },
      e: "Beim Gehen sagt man „Hoşça kalın“ (Bleiben Sie gut). Die Antwort darauf lautet „Güle güle“ (Geh mit einem Lächeln).",
      n: "Vielen Dank. Auf Wiedersehen!" },
    { s: "Eczacı", g: "m", t: "Güle güle. Geçmiş olsun!", n: "Auf Wiedersehen. Gute Besserung!" }
  ],
  questions: [
    { id: "tr-a2-d01.1", t: "mc", q: "Seit wann hat die Kundin Halsschmerzen?", o: ["seit zwei Tagen", "seit gestern", "seit einer Woche"], a: 0,
      why: { 1: "Gestern war sie beim Arzt („Dün doktora gittim“). Die Halsschmerzen hat sie aber schon „iki gündür“.", 2: "Von einer Woche ist keine Rede: Sie sagt „iki gündür“ (seit zwei Tagen)." },
      e: "„iki gündür“ = seit zwei Tagen. Mit **-dİr** (gündür, haftadır, yıldır) drückt man aus, seit wann etwas andauert." },
    { id: "tr-a2-d01.2", t: "gap", q: "Der Apotheker sagt: „Şurubu günde üç ___ kullanın.“ (dreimal täglich)", a: ["kez", "kere", "defa"],
      wrong: { "kezi": "Nach einer Zahl steht „kez“ ohne Endung: „üç kez“. Eine Akkusativendung ist hier falsch.", "kezler": "Nach Zahlen steht kein Plural: „üç kez“, nicht „üç kezler“." },
      e: "„kez“ (auch „kere“, „defa“) heißt „Mal“. Nach Zahlen bleibt es im Singular: „günde üç kez“ = dreimal am Tag." },
    { id: "tr-a2-d01.3", t: "match", q: "Ordne die Beschwerden zu.", p: [["Başım ağrıyor.", "Ich habe Kopfschmerzen."], ["Ateşim var.", "Ich habe Fieber."], ["Öksürüğüm var.", "Ich habe Husten."], ["Karnım ağrıyor.", "Ich habe Bauchschmerzen."]],
      e: "Mit „ağrımak“ sagst du, wo es wehtut („baş“ → „başım ağrıyor“). Mit „… var“ nennst du, was du hast („ateşim var“, „öksürüğüm var“)." },
    { id: "tr-a2-d01.4", t: "mc", q: "Sprachmittlung: Deine Freundin versteht kein Türkisch und fragt dich: „Was hat der Apotheker zum Schmerzmittel gesagt?“", o: ["Ich soll es nicht auf nüchternen Magen nehmen.", "Ich soll es nur abends nehmen.", "Ich soll es erst nach dem Arztbesuch nehmen."], a: 0,
      why: { 1: "Von „abends“ sagt er nichts. Er sagt: nicht auf nüchternen Magen („aç karnına almayın“).", 2: "Ich war schon beim Arzt, das Rezept liegt vor. Eine Wartezeit nennt der Apotheker nicht." },
      e: "„Aç karnına almayın“ = Nehmen Sie es nicht auf nüchternen Magen. „-mayın“ ist die höfliche verneinte Aufforderung. Beim Sprachmitteln gibst du den Inhalt wieder, nicht jedes Wort." }
  ] });
K.addDialog('tr-a2-d02', {
  level: 'A2', scene: 'otel', title: 'Otelde', sub: 'Im Hotel: Einchecken, Zimmerwunsch und Beschwerde',
  role: 'Hotelgast', roleG: 'm',
  lines: [
    { s: "Resepsiyon", g: "m", t: "İyi akşamlar, hoş geldiniz. Rezervasyonunuz var mı?", n: "Guten Abend, willkommen. Haben Sie eine Reservierung?" },
    { me: true, id: "tr-a2-d02.c1",
      o: ["İyi akşamlar. Evet, Keller adına iki gecelik rezervasyonum var.", "İyi akşamlar. Evet, Keller adına iki gecelik rezervasyonun var.", "Selam! Rezervasyon var, Keller."], a: 0,
      why: { 1: "„rezervasyonun“ heißt „deine Reservierung“. Es ist aber **deine** eigene, also „rezervasyonum“ (meine Reservierung).", 2: "„Selam“ ist ein lockerer Gruß unter Freunden, und der Satz ist ein bloßes Stichwort. An der Rezeption grüßt man mit „İyi akşamlar“ und sagt einen ganzen Satz." },
      e: "„Rezervasyonum var“ = Ich habe eine Reservierung (wörtlich: meine Reservierung ist vorhanden). Mit „… adına“ nennst du den Namen, auf den gebucht ist.",
      n: "Guten Abend. Ja, ich habe für zwei Nächte eine Reservierung auf den Namen Keller." },
    { s: "Resepsiyon", g: "m", t: "Evet, rezervasyonunuzu buldum. İki kişilik oda, kahvaltı dâhil. Deniz manzaralı mı olsun, bahçe manzaralı mı?", n: "Ja, ich habe sie gefunden. Doppelzimmer mit Frühstück. Soll es Meerblick oder Gartenblick sein?" },
    { me: true, id: "tr-a2-d02.c2",
      o: ["Deniz manzaralı olsun, lütfen. Mümkünse üst katta bir oda istiyorum.", "Deniz manzaralı ol, mümkünse üst kat ver.", "Deniz manzaralı olsun, lütfen. Mümkünse üst katta bir oda istiyorsun."], a: 0,
      why: { 1: "„ol“ und „ver“ sind Befehle an eine einzelne Person (sen). Für einen Wunsch sagst du „olsun“ (es soll sein) und „istiyorum“ (ich möchte).", 2: "„istiyorsun“ heißt „du willst“. Du sagst, was **du** möchtest: „istiyorum“." },
      e: "Auf die Frage „… olsun?“ antwortest du mit „… olsun“. Einen Wunsch äußerst du mit „istiyorum“ plus „lütfen“; „mümkünse“ (wenn möglich) macht ihn weicher.",
      n: "Mit Meerblick, bitte. Wenn möglich ein Zimmer in einem oberen Stockwerk." },
    { s: "Resepsiyon", g: "m", t: "Tabii. Dördüncü katta deniz manzaralı bir odamız var. Kahvaltı sabah yediden ona kadar. İşte anahtarınız, iyi geceler!", n: "Gern. Im vierten Stock haben wir ein Zimmer mit Meerblick. Frühstück gibt es morgens von sieben bis zehn. Hier ist Ihr Schlüssel, gute Nacht!" },
    { s: "Resepsiyon", g: "m", t: "Resepsiyon, buyurun.", n: "Rezeption, bitte schön?" },
    { me: true, id: "tr-a2-d02.c3",
      o: ["Merhaba, odamdan arıyorum. Klima bozuk, oda çok sıcak ve uyuyamıyorum.", "Merhaba, odamdan arıyorum. Klima bozuk, oda çok sıcak ve uyumuyorum.", "Klima bozuk, hemen tamir et!"], a: 0,
      why: { 1: "„uyumuyorum“ heißt „ich schlafe nicht“ (als Gewohnheit oder Entscheidung). Gemeint ist „ich kann nicht schlafen“, und das heißt „uyuyamıyorum“.", 2: "„tamir et!“ ist ein Befehl und dazu das „du“. Außerdem fehlt jede Anrede. Einem Hotelmitarbeiter schilderst du das Problem und überlässt ihm die Lösung." },
      e: "Möglichkeit verneinen: Stamm + **-(y)AmA-** + -Iyor („uyuyamıyorum“ = ich kann nicht schlafen). Probleme meldest du sachlich: Was ist kaputt? Was ist die Folge?",
      n: "Hallo, ich rufe von meinem Zimmer aus an. Die Klimaanlage ist kaputt, es ist sehr heiß im Zimmer und ich kann nicht schlafen." },
    { s: "Resepsiyon", g: "m", t: "Çok özür dilerim. Ne yazık ki teknisyenimiz şu an burada değil.", n: "Das tut mir sehr leid. Leider ist unser Techniker gerade nicht da." },
    { me: true, id: "tr-a2-d02.c4",
      o: ["O zaman başka bir odaya geçebilir miyim? Ayrıca bahçeden çok gürültü geliyor.", "O zaman başka bir odada geçebilir miyim? Ayrıca bahçeden çok gürültü geliyor.", "O zaman başka bir oda geçebilir miyim? Ayrıca bahçeden çok gürültü geliyor."], a: 0,
      why: { 1: "„-dA“ (Lokativ) heißt „in/an“. Bei „geçmek“ im Sinn von „wechseln in“ brauchst du das Ziel: „odaya“ (in ein Zimmer) mit **-(y)A**.", 2: "Ohne Endung bleibt unklar, wohin du wechselst. Ein Ziel braucht den Dativ: „odaya geçmek“." },
      e: "Wohin? → Dativ **-(y)A**: „başka bir odaya geçmek“ = in ein anderes Zimmer wechseln. „Ayrıca“ (außerdem) hängt den zweiten Grund an.",
      n: "Kann ich dann in ein anderes Zimmer wechseln? Außerdem kommt viel Lärm aus dem Garten." },
    { s: "Resepsiyon", g: "m", t: "Tabii. Sessiz ve klimalı bir oda verebiliriz. Bavullarınızı biz taşırız. Anlayışınız için teşekkür ederiz.", n: "Selbstverständlich. Wir können Ihnen ein ruhiges Zimmer mit Klimaanlage geben. Ihr Gepäck tragen wir. Vielen Dank für Ihr Verständnis." }
  ],
  questions: [
    { id: "tr-a2-d02.1", t: "mc", q: "Was wünscht sich der Gast für sein Zimmer beim Einchecken?", o: ["Meerblick und ein oberes Stockwerk", "Gartenblick und ein Zimmer im Erdgeschoss", "Meerblick und ein Zimmer ohne Frühstück"], a: 0,
      why: { 1: "Er wählt „deniz manzaralı“ (Meerblick), nicht „bahçe manzaralı“ (Gartenblick). Ein Erdgeschoss wünscht er nicht, sondern „üst kat“.", 2: "Meerblick stimmt, aber das Frühstück ist laut Rezeption „dâhil“ (inklusive); davon will er nichts abziehen." },
      e: "„Deniz manzaralı“ = mit Meerblick, „üst kat“ = oberes Stockwerk. „Kahvaltı dâhil“ heißt: Frühstück inklusive." },
    { id: "tr-a2-d02.2", t: "gap", q: "Der Mitarbeiter sagt: „Kahvaltı sabah yediden ona ___.“ (von sieben bis zehn)", a: ["kadar", "dek"],
      wrong: { "sonra": "„sonra“ heißt „nach“ und passt nicht zu „von … bis“. Das „bis“ ist „kadar“.", "için": "„için“ heißt „für“ und gibt keine Zeitgrenze an. Für „bis“ braucht man „kadar“." },
      e: "„von … bis …“ = **-dAn … -(y)A kadar**: „yediden ona kadar“ (von sieben bis zehn). Die Zahl vor „kadar“ steht im Dativ („ona“ von „on“)." },
    { id: "tr-a2-d02.3", t: "order", q: "Bringe die Wörter in die richtige Reihenfolge.", w: ["geçebilir", "bir", "miyim?", "odaya", "Daha", "sessiz"], a: ["Daha sessiz bir odaya geçebilir miyim?"],
      e: "Das Verb steht am Ende, danach die Fragepartikel „miyim“. Adjektiv und „bir“ stehen vor dem Nomen: „daha sessiz bir oda“ (ein ruhigeres Zimmer), mit Dativ „odaya“ als Ziel." },
    { id: "tr-a2-d02.4", t: "mc", q: "Sprachmittlung: Deine Mutter versteht kein Türkisch. Sie fragt dich: „Was bietet die Rezeption an, nachdem wir uns über die Klimaanlage und den Lärm beschwert haben?“", o: ["Ein ruhiges Zimmer mit Klimaanlage; das Gepäck wird getragen.", "Der Techniker kommt sofort und repariert die Klimaanlage.", "Eine Rückerstattung für die erste Nacht."], a: 0,
      why: { 1: "Der Mitarbeiter sagt gerade das Gegenteil: „teknisyenimiz şu an burada değil“ (unser Techniker ist gerade nicht da).", 2: "Von Geld ist keine Rede. Angeboten wird ein anderes Zimmer („sessiz ve klimalı bir oda“)." },
      e: "„Sessiz ve klimalı bir oda verebiliriz“ = Wir können Ihnen ein ruhiges Zimmer mit Klimaanlage geben. „Bavullarınızı biz taşırız“ = Ihr Gepäck tragen wir." }
  ] });

K.addDialog('tr-a2-d03', {
  level: 'A2', scene: 'ev', title: 'Daire bakmak', sub: 'Wohnungsbesichtigung: Nebenkosten, Kaution und ein tropfender Wasserhahn',
  role: 'Mietinteressentin', roleG: 'f',
  lines: [
    { s: "Emre", g: "m", t: "Merhaba, siz Anna Hanım mısınız? Ben Emre, ev sahibinin oğluyum. Buyurun, daire ikinci katta.", n: "Guten Tag, sind Sie Anna Hanım? Ich bin Emre, der Sohn des Vermieters. Bitte sehr, die Wohnung liegt im zweiten Stock." },
    { me: true, id: "tr-a2-d03.c1",
      o: ["Evet, benim. Memnun oldum, Emre Bey.", "Evet, ben Anna Hanım. Memnun oldum, Emre.", "Evet, benim. Hoş buldum, Emre Bey."], a: 0,
      why: { 1: "Über sich selbst sagt man nie „Hanım“ oder „Bey“. Das ist eine Anrede für andere. Außerdem ist der bloße Vorname „Emre“ bei einem ersten Treffen mit „siz“ zu vertraut.", 2: "„Hoş buldum“ ist die Antwort auf „Hoş geldiniz“. Hier wurdest du aber vorgestellt, deshalb passt „Memnun oldum“." },
      e: "Beim ersten Treffen mit „siz“ gehört „Bey“ (Herr) bzw. „Hanım“ (Frau) hinter den Vornamen des Gegenübers: „Emre Bey“. Auf „Ben Emre“ antwortest du mit „Memnun oldum“.",
      n: "Ja, das bin ich. Freut mich, Emre Bey." },
    { s: "Emre", g: "m", t: "Bu arada galiba yaşıtız. Birbirimize sen diyelim mi?", n: "Übrigens, wir sind wohl gleich alt. Wollen wir uns duzen?" },
    { me: true, id: "tr-a2-d03.c2",
      o: ["Olur, sen diyelim. Aidat ne kadar?", "Olur, sen diyelim. Aidat ne kadar, söyler misiniz?", "Olur, Emre Bey, sen diyelim. Aidat ne kadar?"], a: 0,
      why: { 1: "„söyler misiniz“ ist siz – gerade habt ihr „sen“ vereinbart: „söyler misin?“.", 2: "„Bey“ gehört zum Register „siz“. Wer sich duzt, sagt nur „Emre“. Die Mischung wirkt, als hättest du das Angebot nicht ganz angenommen." },
      e: "Auf „sen diyelim mi?“ antwortest du „Olur“ (einverstanden). Ab dann gilt durchgehend „sen“: kein „Bey/Hanım“, keine Endungen auf -(I)nIz. „Aidat“ ist die monatliche Gebühr für Haus und Gemeinschaftskosten.",
      n: "Gern, dann duzen wir uns. Wie hoch ist das Hausgeld?" },
    { s: "Emre", g: "m", t: "Aidat ayda iki bin lira, ısınma ve temizlik dâhil. Depozito da bir aylık kira.", n: "Das Hausgeld beträgt zweitausend Lira im Monat, Heizung und Reinigung inklusive. Die Kaution beträgt eine Monatsmiete." },
    { me: true, id: "tr-a2-d03.c3",
      o: ["Tamam, anladım. Mutfakta ocak ve çamaşır makinesi var mı?", "Tamam, anladım. Mutfakta ocak ve çamaşır makinesi var mısın?", "Tamam, anladım. Mutfakta ocak ve çamaşır makinesini var mı?"], a: 0,
      why: { 1: "„var mısın“ heißt „bist du vorhanden?“ Die Frage gilt der Sache, nicht der Person: „var mı?“ – ohne Personalendung.", 2: "Bei „var/yok“ ist das Ding das Subjekt, und ein Subjekt steht nie im Akkusativ: „çamaşır makinesi var mı?“" },
      e: "„… var mı?“ = Gibt es …? Das Ding steht ohne Endung davor, der Ort mit Lokativ („mutfakta“). Das ist keine Akkusativ-Situation, auch wenn das Ding bestimmt wirkt.",
      n: "Okay, verstanden. Gibt es in der Küche einen Herd und eine Waschmaschine?" },
    { s: "Emre", g: "m", t: "Evet, ocak da var, çamaşır makinesi de. Ama bak, musluk biraz damlıyor.", n: "Ja, einen Herd gibt es und auch eine Waschmaschine. Aber schau, der Wasserhahn tropft ein bisschen." },
    { me: true, id: "tr-a2-d03.c4",
      o: ["Önce tamirciyi arayabilir misin lütfen? Sonra kira sözleşmesini imzalayalım.", "Önce tamirciyi arayabilir misiniz lütfen? Sonra kira sözleşmesini imzalayalım.", "Önce tamirci ara, sonra sözleşme imzala."], a: 0,
      why: { 1: "„arayabilir misiniz“ ist die Form für „siz“. Ihr habt euch aber gerade auf „sen“ geeinigt – also „arayabilir misin?“.", 2: "Zwei Befehle ohne „lütfen“ klingen auch unter Duzenden barsch, besonders gegenüber dem Sohn des Vermieters, bei dem du Mieterin werden willst. Mit „-(y)Abilir misin?“ bittest du freundlich." },
      e: "Bitte im Register „sen“: Stamm + **-(y)Abilir misin?** („arayabilir misin?“). Mit „-(y)AlIm“ schlägst du etwas gemeinsam vor: „imzalayalım“ (lass uns unterschreiben).",
      n: "Kannst du bitte zuerst den Handwerker anrufen? Danach unterschreiben wir den Mietvertrag." },
    { s: "Emre", g: "m", t: "Tabii, bugün arıyorum. Sözleşmeyi pazartesi imzalayalım mı? O gün depozito ve ilk ayın kirası gerekiyor.", n: "Natürlich, ich rufe ihn heute an. Sollen wir den Vertrag am Montag unterschreiben? An dem Tag brauchen wir die Kaution und die erste Monatsmiete." }
  ],
  questions: [
    { id: "tr-a2-d03.1", t: "mc", q: "Wie hoch ist die Kaution („depozito“)?", o: ["eine Monatsmiete", "zwei Monatsmieten", "zweitausend Lira"], a: 0,
      why: { 1: "Von zwei Monatsmieten ist nicht die Rede, die Kaution ist „bir aylık kira“.", 2: "Zweitausend Lira ist der monatliche „aidat“ (das Hausgeld), nicht die Kaution." },
      e: "„bir aylık kira“ = eine Monatsmiete. Die Kaution und das Hausgeld sind zwei verschiedene Posten: „depozito“ zahlt man einmal, „aidat“ jeden Monat." },
    { id: "tr-a2-d03.2", t: "gap", q: "Emre sagt: „Aidat ayda iki bin lira, ısınma ve temizlik ___.“ (inklusive)", a: ["dâhil", "dahil"],
      wrong: { "için": "„için“ heißt „für“. „Inklusive“ sagt man mit „dâhil“.", "ile": "„ile“ heißt „mit“; so ein Satz wäre ungewöhnlich. Üblich ist „… dâhil“ nach den Dingen, die enthalten sind." },
      e: "„dâhil“ (auch „dahil“) = inklusive. Es steht hinter den enthaltenen Dingen: „ısınma ve temizlik dâhil“. Auch „Kahvaltı dâhil“ (Frühstück inklusive) funktioniert so." },
    { id: "tr-a2-d03.3", t: "match", q: "Ordne die Wörter zur Wohnung zu.", p: [["ev sahibi", "Vermieter/in"], ["kiracı", "Mieter/in"], ["depozito", "Kaution"], ["musluk", "Wasserhahn"]],
      e: "„ev sahibi“ ist wörtlich „Hausbesitzer“, „kiracı“ kommt von „kira“ (Miete). „Depozito“ ist die Kaution, „musluk“ der Wasserhahn („Musluk damlıyor“ = Der Wasserhahn tropft)." },
    { id: "tr-a2-d03.4", t: "mc", q: "Sprachmittlung: Deine Mitbewohnerin versteht kein Türkisch und fragt: „Was müssen wir am Montag zur Vertragsunterschrift mitbringen?“", o: ["Die Kaution und die erste Monatsmiete.", "Nur den Ausweis und einen Gehaltsnachweis.", "Nur die Kaution, die Miete zahlen wir später."], a: 0,
      why: { 1: "Von Ausweis oder Gehaltsnachweis sagt Emre nichts. Er nennt „depozito ve ilk ayın kirası“.", 2: "Er sagt „depozito **ve** ilk ayın kirası“. Die erste Monatsmiete wird also gleich mit der Kaution fällig." },
      e: "„O gün depozito ve ilk ayın kirası gerekiyor“ = An dem Tag braucht man die Kaution und die erste Monatsmiete. „gerekiyor“ heißt „ist nötig“." }
  ] });

K.addDialog('tr-a2-d04', {
  level: 'A2', scene: 'otogar', title: 'Havalimanında', sub: 'Am Flughafen: Verspätung und eine unverständliche Durchsage',
  role: 'Reisender', roleG: 'm',
  lines: [
    { s: "Görevli", g: "m", t: "İyi akşamlar, buyurun. Size nasıl yardımcı olabilirim?", n: "Guten Abend, bitte schön. Wie kann ich Ihnen helfen?" },
    { me: true, id: "tr-a2-d04.c1",
      o: ["İyi akşamlar. İzmir'e uçak biletim var ama az önce bir anons duydum, anlamadım. Uçuşum hakkında bilgi alabilir miyim?", "İyi akşamlar. İzmir'e uçak biletim var ama az önce bir anons duydum, anlamadım. Uçuşum hakkında bilgi ver.", "İyi akşamlar. Bir anons duydum, anlamadım. İzmir uçuş?"], a: 0,
      why: { 1: "„bilgi ver“ ist ein Befehl. Am Schalter bittest du mit „-(y)Abilir miyim?“ (Kann ich … bekommen?).", 2: "Zu knapp: Es fehlt das Verb, und „İzmir uçuş?“ ist nur ein Stichwort. Der Mitarbeiter muss raten, was du willst." },
      e: "Du erklärst kurz die Lage (Ticket, Durchsage nicht verstanden) und bittest dann höflich: „bilgi alabilir miyim?“ „X hakkında“ heißt „über X“, davor steht das Wort ohne Kasusendung (Possessiv ist möglich: „uçuşum hakkında“).",
      n: "Guten Abend. Ich habe ein Flugticket nach Izmir, aber ich habe eben eine Durchsage gehört und nicht verstanden. Kann ich Informationen zu meinem Flug bekommen?" },
    { s: "Görevli", g: "m", t: "Tabii. Uçağınız normalde sekizde kalkıyor ama bugün kırk dakika rötar var. Yeni kalkış saati sekiz kırk.", n: "Gern. Ihr Flug startet normalerweise um acht, aber heute gibt es vierzig Minuten Verspätung. Die neue Abflugzeit ist zwanzig vor neun." },
    { me: true, id: "tr-a2-d04.c2",
      o: ["Anonsta bir kapı numarası da söylediler ama duyamadım. Hangi kapıya gitmeliyim?", "Anonsta bir kapı numarası da söylediler ama duyamadım. Hangi kapıda gitmeliyim?", "Anonsta bir kapı numarası da söylediler ama duyamadım. Hangi kapıya gitmelisin?"], a: 0,
      why: { 1: "„-da“ (Lokativ) heißt „wo?“, gefragt ist „wohin?“ → „kapıya“.", 2: "„gitmelisin“ heißt „du musst gehen“. Du fragst nach dir selbst: „gitmeliyim“ (ich muss gehen). Außerdem wäre „sen“ gegenüber dem Mitarbeiter unpassend." },
      e: "Wohin? → Dativ **-(y)A**: „kapıya gitmek“. Pflicht: Stamm + **-mAlI** + Personalendung: „gitmeliyim“ = ich muss gehen. „duyamadım“ = ich konnte nicht hören (-(y)AmA- = nicht können).",
      n: "In der Durchsage wurde auch eine Gate-Nummer genannt, aber ich konnte sie nicht hören. Zu welchem Gate muss ich gehen?" },
    { s: "Görevli", g: "m", t: "Kapı on dört. Ama kapı değişebilir, lütfen ekrana ve anonslara dikkat edin.", n: "Gate vierzehn. Aber das Gate kann sich ändern, achten Sie bitte auf die Anzeigetafel und die Durchsagen." },
    { me: true, id: "tr-a2-d04.c3",
      o: ["İstanbul'da aktarma yapacağım. Rötar yüzünden aktarma uçağımı kaçırır mıyım?", "İstanbul'da aktarma yapacağım. Rötar yüzünden aktarma uçağımı kaçırdım mı?", "İstanbul'da aktarma yapacağım. Rötar yüzünden aktarma uçağınızı kaçıracak mısınız?"], a: 0,
      why: { 1: "„kaçırdım mı?“ fragt, ob du den Anschluss **schon verpasst hast**. Der Anschlussflug liegt aber noch in der Zukunft. Gefragt ist „Werde ich … verpassen?“: „kaçırır mıyım?“.", 2: "„kaçıracak mısınız“ heißt „Werden Sie verpassen?“ und „uçağınızı“ „Ihren Flug“. Es geht aber um **deinen** Flug: „uçağımı“, „kaçırır mıyım?“." },
      e: "Aorist-Frage: **-(I)r mI** + Person („kaçırır mıyım?“) = Werde ich … verpassen? Sie fragt nach einer möglichen Folge. „Rötar yüzünden“ = wegen der Verspätung („yüzünden“ steht hinter dem Grund). „uçağımı kaçırmak“ = meinen Flug verpassen; „uçağım“ ist bestimmt (mein Flug), daher Akkusativ.",
      n: "Ich muss in Istanbul umsteigen. Werde ich wegen der Verspätung meinen Anschlussflug verpassen?" },
    { s: "Görevli", g: "m", t: "Merak etmeyin. Aktarma uçağınız on bir buçukta kalkıyor, zamanınız yeterli.", n: "Keine Sorge. Der Anschlussflug geht erst um halb zwölf, Sie haben genug Zeit." },
    { me: true, id: "tr-a2-d04.c4",
      o: ["Çok teşekkür ederim, kolay gelsin!", "Çok teşekkür ederim, iyi yolculuklar!", "Sağ ol, hoşça kal!"], a: 0,
      why: { 1: "„İyi yolculuklar“ wünscht man jemandem, der **verreist**. Der Mitarbeiter fährt nicht weg, er arbeitet.", 2: "„Sağ ol“ und „hoşça kal“ sind „sen“-Formen. Zu einem Fremden am Schalter passt „Sağ olun“ oder „Teşekkür ederim“ und „Hoşça kalın“." },
      e: "„Kolay gelsin“ (wörtlich: möge es leicht gehen) wünscht man Leuten bei der Arbeit. Es ist ein freundlicher Abschluss an Schaltern und in Geschäften.",
      n: "Vielen Dank, und frohes Schaffen!" },
    { s: "Görevli", g: "m", t: "Rica ederim. İyi yolculuklar!", n: "Gern geschehen. Gute Reise!" }
  ],
  questions: [
    { id: "tr-a2-d04.1", t: "mc", q: "Wie lange hat der Flug Verspätung?", o: ["vierzig Minuten", "eine halbe Stunde", "zwei Stunden"], a: 0,
      why: { 1: "Eine halbe Stunde wären „otuz dakika“ (dreißig). Der Mitarbeiter sagt „kırk dakika“ (vierzig).", 2: "Zwei Stunden nennt niemand. Die Verspätung beträgt „kırk dakika“." },
      e: "„kırk dakika rötar var“ = Es gibt vierzig Minuten Verspätung. „rötar“ ist die Verspätung bei Flug oder Bahn, beim Bus sagt man eher „gecikme“." },
    { id: "tr-a2-d04.2", t: "gap", q: "Setze die richtige Endung ein: „Hangi kapı___ gitmeliyim?“ (Wohin muss ich gehen?)", a: ["ya"],
      wrong: { "dan": "„-dan“ hieße „durch welches Gate / von welchem Gate“, gefragt ist „wohin?“.", "da": "„-da“ (Lokativ) heißt „wo?“, gefragt ist „wohin?“ → „kapıya“.", "ye": "Das Ziel ist richtig (Dativ), aber die Vokalharmonie nicht. „kapı“ endet auf „ı“ (hinterer Vokal), also „-ya“.", "yı": "„-yı“ ist Akkusativ. „gitmek“ verlangt aber das Ziel im Dativ." },
      e: "Auf „wohin?“ antwortet der **Dativ**: „kapıya“. Nach einem Vokal schiebt sich ein **-y-** ein (kapı + y + a), und nach hinteren Vokalen (a, ı, o, u) steht -a." },
    { id: "tr-a2-d04.3", t: "order", q: "Bringe die Wörter in die richtige Reihenfolge.", w: ["Rötar", "yüzünden", "aktarma", "uçağımı", "kaçırır", "mıyım?"], a: ["Rötar yüzünden aktarma uçağımı kaçırır mıyım?"],
      e: "Der Grund „Rötar yüzünden“ steht vorn, dann das Objekt „aktarma uçağımı“. Das Verb im Aorist („kaçırır“) und die Fragepartikel „mıyım“ kommen ans Ende." },
    { id: "tr-a2-d04.4", t: "match", q: "Ordne die Wörter vom Flughafen zu.", p: [["rötar", "Verspätung"], ["uçuş", "Flug"], ["aktarma", "Umstieg"], ["yolcu", "Fluggast, Reisender"]],
      e: "„rötar“, „uçuş“, „aktarma“ und „yolcu“ kommen am Flughafen und Busbahnhof ständig vor. „Aktarma yapmak“ heißt umsteigen." }
  ] });

K.addDialog('tr-a2-d05', {
  level: 'A2', scene: 'bayram', title: 'Bayram daveti', sub: 'Einladung zum Bayram: unter Freunden duzen, Ältere siezen',
  role: 'Eingeladene', roleG: 'f',
  lines: [
    { s: "Deniz", g: "m", t: "Selam Lena! Bayramda ne yapıyorsun? Annemler seni bayramın ilk günü yemeğe bekliyor, gelir misin?", n: "Hallo Lena! Was machst du am Bayram? Meine Eltern erwarten dich am ersten Tag des Festes zum Essen. Kommst du?" },
    { me: true, id: "tr-a2-d05.c1",
      o: ["Çok sevinirim, davetin için teşekkürler! Saat kaçta gelebilirim?", "Çok sevinirim, davetin için teşekkürler! Saat kaçta gelebilirim, Deniz Bey?", "Çok sevinirim, davetin için teşekkürler! Saat kaçta gelebilirsin?"], a: 0,
      why: { 1: "„Bey“ gehört zum siz-Register. Einen Freund, den du duzt, sprichst du nur mit dem Vornamen an.", 2: "„gelebilirsin“ heißt „du kannst kommen“. Du fragst, wann du selbst kommen kannst: „gelebilirim“." },
      e: "Unter Freunden gilt „sen“: „davetin için teşekkürler“. Die Frage nach der eigenen Möglichkeit steht in der 1. Person: „gelebilirim“. „Çok sevinirim“ = Ich würde mich sehr freuen (Aorist).",
      n: "Ich würde mich sehr freuen, danke für deine Einladung! Um wie viel Uhr kann ich kommen?" },
    { s: "Deniz", g: "m", t: "Öğleden sonra iki gibi gel. Annem sarma ve baklava yapacak, babaannem de gelecek. Kalabalık olacak ama herkes çok cana yakın.", n: "Komm gegen zwei am Nachmittag. Meine Mutter macht gefüllte Weinblätter und Baklava, meine Oma kommt auch. Es wird voll, aber alle sind sehr herzlich." },
    { me: true, id: "tr-a2-d05.c2",
      o: ["Eli boş gelmek istemiyorum. Annene çikolata götürebilirim, olur mu?", "Eli boş gelmek istemiyorum. Annenize çikolata götürebilirim, olur mu?", "Eli boş gelmek istemiyorum. Annen çikolata götürebilirim, olur mu?"], a: 0,
      why: { 1: "„Annenize“ ist die „siz“-Form (Ihrer Mutter). Deniz duzt du, also „annene“ (deiner Mutter).", 2: "„Annen“ bedeutet „deine Mutter“ als Subjekt. Wem du etwas mitbringst, steht im Dativ: „annene“ (deiner Mutter)." },
      e: "Possessiv + Dativ: anne + **n** (dein) + **e** (der Mutter) = „annene“. Bei Verwandten steht oft das Possessiv: „annem“ (meine Mutter), „annen“ (deine Mutter). „Olur mu?“ fragt: Ist das in Ordnung?",
      n: "Ich möchte nicht mit leeren Händen kommen. Ich könnte deiner Mutter Schokolade mitbringen, wäre das in Ordnung?" },
    { s: "Deniz", g: "m", t: "Hiç gerek yok ama çok düşüncelisin! Çikolata olur, annem çok sever. Bir şey daha: babaannem biraz geleneksel, ona siz demelisin.", n: "Das wäre gar nicht nötig, aber du bist sehr aufmerksam! Schokolade ist gut, meine Mutter mag sie sehr. Noch etwas: Meine Oma ist ein bisschen traditionell, du musst sie siezen." },
    { me: true, id: "tr-a2-d05.c3",
      o: ["Tamam. Ona „Bayramınız kutlu olsun“ diyeceğim, doğru mu?", "Tamam. Ona „Bayramın kutlu olsun“ diyeceğim, doğru mu?", "Tamam. Ona „Bayramınız kutlu olsun“ demelisiniz, doğru mu?"], a: 0,
      why: { 1: "„Bayramın kutlu olsun“ ist die „sen“-Form für Freunde. Deniz hat gerade gesagt, dass du seine Oma siezen sollst.", 2: "„demelisiniz“ heißt „Sie müssen sagen“. Du sprichst von dir selbst: „diyeceğim“ (ich werde sagen) oder „demeliyim“ (ich muss sagen)." },
      e: "Glückwunsch zum Fest: „sen“ → „Bayramın kutlu olsun“, „siz“ → „Bayramınız kutlu olsun“. Zu Älteren, die du nicht gut kennst, benutzt du immer „siz“. Futur: „demek“ → „diyeceğim“: Stammvokal e → i (wie „yemek“ → „yiyeceğim“), Bindungs-y, k → ğ vor Vokal.",
      n: "Okay. Ich sage zu ihr „Bayramınız kutlu olsun“, stimmt das?" },
    { s: "Deniz", g: "m", t: "Evet, tam doğru! Bayramda büyüklerin elini öperiz, onu da sana göstereceğim. Bir şey sorayım: acı yer misin? Annem ona göre yapsın.", n: "Ja, genau richtig! Am Bayram küssen wir den Älteren die Hand, das zeige ich dir auch. Ich frage noch: Isst du scharf? Meine Mutter soll sich danach richten." },
    { me: true, id: "tr-a2-d05.c4",
      o: ["Her şeyi yerim ama acıyı pek sevmem. Acı olmasın lütfen.", "Her şeyi yerim ama acıyı pek sevmedim. Acı olmasın lütfen.", "Her şeyi yerim ama acıyı pek sevmem. Acı olmayın lütfen."], a: 0,
      why: { 1: "„sevmedim“ ist die einmalige Vergangenheit („ich mochte es nicht“). Eine allgemeine Vorliebe drückst du mit dem Aorist aus: „sevmem“ (ich mag nicht).", 2: "„olmayın“ ist eine verneinte Aufforderung an mehrere Personen oder an eine gesiezte Person („seid/seien Sie nicht“). Das Essen soll nicht scharf sein: „olmasın“ (es soll nicht sein)." },
      e: "Allgemeine Vorlieben: Aorist („her şeyi yerim“, „sevmem“). Wunsch für eine Sache: 3. Person Imperativ „-sIn“, verneint „-mAsIn“: „acı olmasın“ = es soll nicht scharf sein.",
      n: "Ich esse alles, aber scharf mag ich nicht so. Bitte nicht scharf." },
    { s: "Deniz", g: "m", t: "Tamam, anneme söylerim. O zaman görüşürüz, şimdiden bayramın kutlu olsun, Lena!", n: "Alles klar, ich sage es meiner Mutter. Dann bis bald, schon jetzt ein frohes Fest, Lena!" }
  ],
  questions: [
    { id: "tr-a2-d05.1", t: "mc", q: "Was möchte Lena zum Essen bei Deniz' Familie mitbringen?", o: ["Schokolade", "Baklava", "Blumen"], a: 0,
      why: { 1: "Baklava macht Deniz' Mutter selbst („Annem baklava yapacak“). Lena bringt „çikolata“.", 2: "Von Blumen ist nicht die Rede. Lena schlägt „çikolata“ (Schokolade) vor." },
      e: "Lena sagt: „Annene çikolata götürebilirim.“ Çikolata heißt Schokolade. Ein kleines Mitbringsel beim Besuch zum Bayram ist üblich." },
    { id: "tr-a2-d05.2", t: "gap", q: "Setze die Endung ein. Deniz zu Lena (duzen): „Şimdiden bayram___ kutlu olsun!“ (Frohes Fest!)", a: ["ın"],
      wrong: { "ınız": "„-ınız“ ist die „siz“-Form. Zu einer Freundin, die du duzt, sagst du „bayramın“.", "ım": "„bayramım“ heißt „mein Fest“. Du wünschst aber **ihr** (der Person, mit der du sprichst) ein frohes Fest: „bayramın“.", "in": "Das ist die richtige Person, aber die Vokalharmonie stimmt nicht. „bayram“ endet auf „a“ (hinterer Vokal), also „-ın“." },
      e: "Possessiv der 2. Person Singular nach Konsonant: bayram + **ın** = bayramın (dein Fest). Die Vokalharmonie: hinterer Vokal a → ı. Zu mehreren oder zu einer respektierten Person heißt es „bayramınız“." },
    { id: "tr-a2-d05.3", t: "match", q: "Ordne die Glückwünsche der passenden Situation zu.", p: [["Bayramın kutlu olsun!", "Frohes Fest, an einen Freund (du)"], ["Bayramınız kutlu olsun!", "Frohes Fest, an die Großmutter (Sie)"], ["Doğum günün kutlu olsun!", "Alles Gute zum Geburtstag, an einen Freund (du)"], ["İyi bayramlar!", "Schönes Fest! Kurzer Gruß an alle"]],
      e: "„-ın“ ist die Endung für „sen“, „-ınız“ für „siz“ (oder für mehrere Personen). „İyi bayramlar“ passt in jedem Register, weil es keine Endung für die Person trägt." },
    { id: "tr-a2-d05.4", t: "mc", q: "Sprachmittlung: Deine Schwester versteht kein Türkisch und fragt dich: „Was hat Deniz über seine Oma gesagt?“", o: ["Sie ist traditionell, deshalb soll ich sie siezen.", "Sie ist locker, ich kann sie duzen wie Deniz.", "Sie kommt dieses Jahr nicht zum Fest."], a: 0,
      why: { 1: "Deniz sagt das Gegenteil: „babaannem biraz geleneksel, ona siz demelisin“. „Sen“ ist für Freunde und Gleichaltrige.", 2: "„babaannem de gelecek“ – sie kommt." },
      e: "„Ona siz demelisin“ = Du musst sie siezen. Die Oma ist älter und traditionell, deshalb gilt „siz“ (Endungen -(I)nIz, -sInIz). Zu Gleichaltrigen und Freunden sagt man „sen“." }
  ] });

K.addDialog('tr-a2-d06', {
  level: 'A2', scene: 'alisveris', title: 'Mağazada', sub: 'Im Bekleidungsgeschäft: anprobieren, handeln, Umtausch klären (Verkäufer siezen)',
  role: 'Kunde', roleG: 'm',
  lines: [
    { s: "Satıcı", g: "f", t: "Hoş geldiniz, buyurun. Size yardımcı olabilir miyim?", n: "Herzlich willkommen, bitte sehr. Kann ich Ihnen helfen?" },
    { me: true, id: "tr-a2-d06.c1",
      o: ["Merhaba, kendime bir mont arıyorum. Siyah olanı denemek istiyorum.", "Merhaba, kendime bir mont arıyorsun. Siyah olanı denemek istiyorum.", "Merhaba, kendime bir mont arıyorum. Siyah olan denemek istiyorum."], a: 0,
      why: { 1: "„arıyorsun“ heißt „du suchst“. Du sprichst von dir selbst, also „arıyorum“ (ich suche).", 2: "„Siyah olan“ (der schwarze) ist hier ein bestimmtes Stück, das du meinst. Ein bestimmtes Objekt bekommt den Akkusativ: „siyah olanı“." },
      e: "Ein bestimmtes Objekt steht im Akkusativ: „siyah olanı denemek istiyorum“. „-mAk istiyorum“ = ich möchte … (Infinitiv + istemek). „Kendime“ = für mich selbst.",
      n: "Guten Tag, ich suche eine Jacke für mich. Ich möchte die schwarze anprobieren." },
    { s: "Satıcı", g: "f", t: "Tabii, buyurun, kabin sağda.", n: "Natürlich, bitte sehr, die Umkleide ist rechts." },
    { s: "Satıcı", g: "f", t: "Çok yakıştı! Fiyatı bin sekiz yüz lira.", n: "Das steht Ihnen sehr gut! Der Preis ist 1.800 Lira." },
    { me: true, id: "tr-a2-d06.c2",
      o: ["Biraz pahalı. İndirim yapabilir misiniz?", "Biraz ucuz. İndirim yapabilir misiniz?", "Biraz pahalı. İndirim yapabilir misin?"], a: 0,
      why: { 1: "„ucuz“ heißt „billig“. Wer etwas billig findet, bittet nicht um Rabatt. Du findest den Preis hoch: „pahalı“ (teuer).", 2: "„yapabilir misin“ ist die „sen“-Form. Der Verkäuferin gegenüber, die du nicht kennst, passt „siz“: „yapabilir misiniz“." },
      e: "Beim Handeln bleibt man höflich: „İndirim yapabilir misiniz?“ (Können Sie Rabatt geben?). „-(y)Abilir misiniz?“ ist die höfliche Bitte an eine Person, die man siezt.",
      n: "Ein bisschen teuer. Können Sie mir Rabatt geben?" },
    { s: "Satıcı", g: "f", t: "Peki, size özel bir fiyat yapayım: bin altı yüz lira. Daha fazla indirim yapamam.", n: "Gut, ich mache Ihnen einen Sonderpreis: 1.600 Lira. Mehr Rabatt kann ich nicht geben." },
    { me: true, id: "tr-a2-d06.c3",
      o: ["Tamam, alıyorum. Uymazsa değiştirebilir miyim?", "Tamam, almıyorum. Uymazsa değiştirebilir miyim?", "Tamam, alıyorum. Uymazsa değiştirebilirsin."], a: 0,
      why: { 1: "„almıyorum“ heißt „ich kaufe nicht“. Das widerspricht der Frage nach dem Umtausch. Du entscheidest dich zum Kauf: „alıyorum“.", 2: "„değiştirebilirsin“ heißt „du kannst umtauschen“ und ist keine Frage. Du fragst, was **du** darfst: „değiştirebilir miyim?“." },
      e: "„Tamam, alıyorum“ = Gut, ich nehme sie (Präsens für eine Entscheidung im Moment). „Uymazsa“ = wenn sie nicht passt: verneinter Aorist -mAz + Bedingung -sA („uy-maz-sa“).",
      n: "Gut, ich nehme sie. Kann ich sie umtauschen, falls sie nicht passt?" },
    { s: "Satıcı", g: "f", t: "Tabii, on beş gün içinde fişle değiştirebilirsiniz. Fişi saklamayı unutmayın. Nakit mi ödeyeceksiniz, kartla mı?", n: "Natürlich, innerhalb von 15 Tagen können Sie sie mit dem Kassenbon umtauschen. Vergessen Sie nicht, den Bon aufzubewahren. Zahlen Sie bar oder mit Karte?" },
    { me: true, id: "tr-a2-d06.c4",
      o: ["Kartla ödeyeceğim. Bir poşet alabilir miyim?", "Kartla ödeyeceğim. Bir poşet alabilirim mi?", "Kartla ödeyeceğim. Bir poşet alabilirsiniz?"], a: 0,
      why: { 1: "Die Fragepartikel kommt **nach** dem Verb, und die Personenendung wandert an sie: „alabilir miyim?“. „alabilirim mi“ ist falsch gebaut.", 2: "„alabilirsiniz“ heißt „Sie können nehmen“. Du fragst, ob **du** eine Tüte nehmen darfst: „alabilir miyim?“." },
      e: "Frage mit Möglichkeit: Verbstamm + -(y)Abilir + **mi** + Personenendung: „alabilir miyim?“. „Kartla“ = mit der Karte (-lA, nach Konsonant „-la“). In der Türkei kosten Tüten meist extra, trotzdem fragt man höflich so.",
      n: "Ich zahle mit Karte. Kann ich eine Tüte bekommen?" },
    { s: "Satıcı", g: "f", t: "Elbette, buyurun poşetiniz. Güle güle giyin, iyi günler!", n: "Selbstverständlich, bitte sehr, Ihre Tüte. Viel Freude damit, einen schönen Tag!" }
  ],
  questions: [
    { id: "tr-a2-d06.1", t: "mc", q: "Wie endet das Handeln um den Preis?", o: ["Die Verkäuferin geht von 1.800 auf 1.600 Lira herunter.", "Der Preis bleibt bei 1.800 Lira.", "Die Verkäuferin geht auf 1.200 Lira herunter."], a: 0,
      why: { 1: "Die Verkäuferin lässt etwas nach: „bin altı yüz lira“ (1.600).", 2: "1.200 Lira wird nicht genannt. Sie sagt „bin altı yüz“ (1.600) und „daha fazla indirim yapamam“ (mehr Rabatt kann ich nicht geben)." },
      e: "Zuerst „bin sekiz yüz lira“ (1.800), nach der Bitte um Rabatt „bin altı yüz lira“ (1.600). „Daha fazla indirim yapamam“ heißt: mehr Nachlass ist nicht möglich." },
    { id: "tr-a2-d06.2", t: "gap", q: "Die Verkäuferin sagt: „Fişle on beş gün ___ değiştirebilirsiniz.“ (innerhalb von 15 Tagen)", a: ["içinde", "içerisinde", "zarfında"],
      wrong: { "için": "„için“ heißt „für“ oder „wegen“. Ein Zeitraum, innerhalb dessen etwas gilt, wird mit „içinde“ ausgedrückt.", "sonra": "„sonra“ heißt „nach“. Gemeint ist aber „innerhalb“ von 15 Tagen: „içinde“.", "boyunca": "„boyunca“ heißt „während, über den ganzen Zeitraum hinweg“ („yıl boyunca“ = das ganze Jahr über). Eine Frist, innerhalb der etwas möglich ist, heißt „içinde“ oder „zarfında“." },
      e: "„on beş gün içinde“ = innerhalb von 15 Tagen. „içinde“ (in, innerhalb) steht hinter dem Zeitraum. Nach der Zahl bleibt „gün“ im Singular." },
    { id: "tr-a2-d06.3", t: "match", q: "Ordne die Einkaufswörter zu.", p: [["indirim", "Preisnachlass"], ["fiş", "Kassenbon"], ["beden", "Konfektionsgröße"], ["değiştirmek", "umtauschen"]],
      e: "„indirim yapmak“ = Rabatt geben, „fişle değiştirmek“ = mit dem Bon umtauschen. „Beden“ ist die Kleidergröße, z. B. „kaç beden giyiyorsunuz?“ (Welche Größe tragen Sie?)." },
    { id: "tr-a2-d06.4", t: "order", q: "Bilde die höfliche Bitte: „Können Sie mir Rabatt geben?“", w: ["İndirim", "misiniz", "yapabilir"], a: ["İndirim yapabilir misiniz"],
      e: "Das Verb mit der Möglichkeitsendung „yapabilir“ steht vor der Fragepartikel „misiniz“. „misiniz“ steht immer getrennt vom Verb. Das Objekt „indirim“ steht davor, das Verb am Ende." },
    { id: "tr-a2-d06.5", t: "mc", q: "Sprachmittlung: Dein Freund versteht kein Türkisch und fragt dich: „Was passiert, wenn dir die Jacke nicht passt?“", o: ["Ich kann sie innerhalb von 15 Tagen mit dem Kassenbon umtauschen.", "Umtausch ist nur ohne Kassenbon möglich.", "Gekaufte Jacken werden nie umgetauscht."], a: 0,
      why: { 1: "Es heißt „fişle değiştirebilirsiniz“: nur mit dem Bon, deshalb soll man ihn aufbewahren.", 2: "Die Verkäuferin bietet den Umtausch ausdrücklich an: „on beş gün içinde … değiştirebilirsiniz“." },
      e: "„Fişle“ = mit dem Bon. „Fişi saklamayı unutmayın“ = Vergessen Sie nicht, den Bon aufzubewahren. Beim Sprachmitteln gibst du die wichtigen Bedingungen wieder: Frist und Bon." }
  ] });

K.addDialog('tr-a2-d07', {
  level: 'A2', scene: 'banka', title: 'Bankada', sub: 'Karte verloren: neue Karte per Kurier, neue Rufnummer und SMS-Code (Bankangestellte siezen)',
  role: 'Kundin', roleG: 'f',
  lines: [
    { s: "Görevli", g: "f", t: "Hoş geldiniz, size nasıl yardımcı olabilirim?", n: "Willkommen, wie kann ich Ihnen helfen?" },
    { me: true, id: "tr-a2-d07.c1",
      o: ["Merhaba, banka kartımı kaybettim. Kartı iptal etmek istiyorum.", "Merhaba, banka kartımı kaybettin. Kartı iptal etmek istiyorum.", "Merhaba, banka kartı kaybettim. Kartı iptal etmek istiyorum."], a: 0,
      why: { 1: "„kaybettin“ heißt „du hast verloren“. Du sprichst von dir: „kaybettim“ (ich habe verloren).", 2: "„banka kartı“ allein sagt nicht, wessen Karte. Es ist deine Karte und ein bestimmtes Objekt: „banka kartımı“ (mit Possessiv und Akkusativ)." },
      e: "Meine Karte (bestimmt) = Possessiv + Akkusativ: banka kart**ım**+**ı**. Vergangenheit auf -dI: „kaybet-ti-m“ (nach hartem Konsonanten t statt d).",
      n: "Guten Tag, ich habe meine Bankkarte verloren. Ich möchte die Karte sperren lassen." },
    { s: "Görevli", g: "f", t: "Geçmiş olsun. Kimliğinizi alabilir miyim? Hemen iptal ediyorum. Yeni bir kart çıkarabiliriz, kart üç iş günü içinde kargoyla adresinize gelir.", n: "Das tut mir leid. Darf ich Ihren Ausweis haben? Ich sperre sie sofort. Wir können eine neue Karte ausstellen, sie kommt innerhalb von drei Werktagen per Kurier zu Ihrer Adresse." },
    { me: true, id: "tr-a2-d07.c2",
      o: ["Geçen ay taşındım. Kartı yeni adresime gönderebilir misiniz?", "Geçen ay taşınıyorum. Kartı yeni adresime gönderebilir misiniz?", "Geçen ay taşındım. Kartı yeni adresime gönderebilir misin?"], a: 0,
      why: { 1: "„geçen ay“ (letzten Monat) verlangt die Vergangenheit: „taşındım“. „taşınıyorum“ heißt „ich ziehe gerade um“.", 2: "„gönderebilir misin“ ist die „sen“-Form. Einer Bankangestellten gegenüber benutzt du „siz“: „gönderebilir misiniz“." },
      e: "Mit „geçen ay“, „dün“, „geçen hafta“ steht die Vergangenheit auf -dI. Eine höfliche Bitte an eine gesiezte Person: „-(y)Abilir misiniz?“.",
      n: "Ich bin letzten Monat umgezogen. Können Sie die Karte an meine neue Adresse schicken?" },
    { s: "Görevli", g: "f", t: "Tabii, yeni adresinizi yazıyorum. Telefon numaranız hâlâ aynı mı? Kart gelince kurye sizi arayacak.", n: "Natürlich, ich notiere Ihre neue Adresse. Ist Ihre Telefonnummer noch dieselbe? Wenn die Karte kommt, ruft der Kurier Sie an." },
    { me: true, id: "tr-a2-d07.c3",
      o: ["Hayır, numaram değişti. Yeni numaramı söyleyeyim.", "Hayır, numaram değişti. Yeni numaramı söylesin.", "Hayır, numaram değişmedi. Yeni numaramı söyleyeyim."], a: 0,
      why: { 1: "„söylesin“ heißt „er/sie soll sagen“. Du bietest an, die Nummer selbst zu nennen: „söyleyeyim“ (lass mich sagen).", 2: "„değişmedi“ heißt „hat sich nicht geändert“. Dann gäbe es keine neue Nummer. Richtig ist „değişti“ (hat sich geändert)." },
      e: "Angebot oder Vorschlag in der 1. Person: **-(y)AyIm** („söyle-yeyim“ = soll ich sagen / lassen Sie mich sagen). „Numaram değişti“ = meine Nummer hat sich geändert.",
      n: "Nein, meine Nummer hat sich geändert. Ich sage Ihnen die neue Nummer." },
    { s: "Görevli", g: "f", t: "Teşekkürler, güncelledim. Şimdi telefonunuza SMS ile bir doğrulama kodu gelecek. Kodu şu ekrana girer misiniz?", n: "Danke, ich habe sie aktualisiert. Jetzt kommt per SMS ein Bestätigungscode auf Ihr Telefon. Geben Sie ihn bitte auf diesem Bildschirm ein?" },
    { me: true, id: "tr-a2-d07.c4",
      o: ["Henüz gelmedi. Tekrar gönderebilir misiniz?", "Henüz gelmedim. Tekrar gönderebilir misiniz?", "Henüz gelmedi. Tekrar gönderebilir misin?"], a: 0,
      why: { 1: "„gelmedim“ heißt „ich bin nicht gekommen“. Es geht um den Code, also die 3. Person: „gelmedi“ (er ist nicht gekommen).", 2: "„gönderebilir misin“ ist „sen“. Der Bankangestellten gegenüber bleibst du bei „siz“: „gönderebilir misiniz“." },
      e: "Die 3. Person Singular hat bei -dI keine Endung: „gel-me-di“ (er/sie/es ist nicht gekommen). „Henüz“ + Verneinung = noch nicht.",
      n: "Er ist noch nicht angekommen. Können Sie ihn noch einmal schicken?" },
    { s: "Görevli", g: "f", t: "Tekrar gönderdim, bir bakın lütfen. Kodu girdikten sonra işlemi bitiririm. Kartınız kargoyla adresinize gelecek. İyi günler dilerim!", n: "Ich habe ihn noch einmal geschickt, schauen Sie bitte nach. Wenn Sie den Code eingegeben haben, schließe ich den Vorgang ab. Ihre Karte kommt per Kurier an Ihre Adresse. Einen schönen Tag noch!" }
  ],
  questions: [
    { id: "tr-a2-d07.1", t: "mc", q: "Wie bekommt die Kundin ihre neue Karte?", o: ["Per Kurier an die neue Adresse, in drei Werktagen.", "Sie muss sie in der Filiale abholen.", "Sie kommt per Post an die alte Adresse."], a: 0,
      why: { 1: "Es heißt „kargoyla adresinize gelir“: Die Karte kommt zu ihr, sie holt sie nicht ab.", 2: "Die Kundin gibt ihre **neue** Adresse an („yeni adresime gönderebilir misiniz“)." },
      e: "„kargoyla“ = per Kurier oder Paketdienst. „Üç iş günü içinde“ = innerhalb von drei Werktagen. „adresinize“ = an Ihre Adresse (Possessiv -iniz + Dativ -e)." },
    { id: "tr-a2-d07.2", t: "gap", q: "Setze die Endung ein: „Banka kartım___ kaybettim.“ (Ich habe meine Bankkarte verloren.)", a: ["ı"],
      wrong: { "i": "Die Vokalharmonie stimmt nicht. „kartım“ endet auf „ı“, einen hinteren Vokal, also folgt „-ı“.", "yı": "Das Bindungs-y steht nur nach einem Vokal. „kartım“ endet auf „m“, also kommt „-ı“ direkt dahinter." },
      e: "Meine Karte (bestimmt) = Akkusativ: kart + **ım** (mein) + **ı** (Akkusativ) = kartımı. Der Akkusativ richtet sich nach dem letzten Vokal („ı“), und nach Konsonant steht kein Bindungs-y." },
    { id: "tr-a2-d07.3", t: "match", q: "Ordne die Wörter zu.", p: [["kimlik", "Ausweis"], ["hesap", "Konto"], ["kurye", "Kurier"], ["hat", "Mobilfunkanschluss mit Nummer"]],
      e: "„Kimlik“ ist jedes Ausweisdokument. „Hat“ meint den Anschluss bei einem Mobilfunkanbieter, „yeni bir hat almak“ = einen neuen Anschluss bekommen. „Kurye“ liefert Pakete oder Karten." },
    { id: "tr-a2-d07.4", t: "order", q: "Bilde die höfliche Bitte: „Können Sie die Karte an meine neue Adresse schicken?“", w: ["gönderebilir", "Kartı", "misiniz", "adresime", "yeni"], a: ["Kartı yeni adresime gönderebilir misiniz", "Yeni adresime kartı gönderebilir misiniz"],
      e: "„Kartı“ steht vorn, danach das Ziel „yeni adresime“ (Dativ), am Ende das Verb mit „misiniz“. Die Fragepartikel steht getrennt." },
    { id: "tr-a2-d07.5", t: "mc", q: "Sprachmittlung: Deine Freundin versteht kein Türkisch und fragt: „Wozu bekommt die Kundin den Code per SMS?“", o: ["Er bestätigt die neue Telefonnummer, sie gibt ihn am Bildschirm ein.", "Er öffnet ihr neues Konto.", "Er ist die Nummer der Karte."], a: 0,
      why: { 1: "Es geht nicht um ein neues Konto. Die Nummer wurde geändert, und der Code dient dazu, das zu bestätigen („doğrulama kodu“).", 2: "Die Kartennummer kommt später mit der Karte. Der SMS-Code ist ein „doğrulama kodu“ (Bestätigungscode)." },
      e: "„Doğrulamak“ heißt bestätigen oder verifizieren. Die Bank schickt den Code an die neue Nummer. Die Kundin gibt ihn auf dem Bildschirm ein („ekrana girmek“), so ist sicher, dass die Nummer ihr gehört." }
  ] });

K.addDialog('tr-a2-d08', {
  level: 'A2', scene: 'is', title: 'İş yerinde', sub: 'Büro: mit dem Kollegen per du, mit dem Chef per Sie – Besprechung, E-Mail und Urlaub',
  role: 'Mitarbeiterin', roleG: 'f',
  lines: [
    { s: "Mert", g: "m", t: "Günaydın Lena! Bugünkü toplantıyı unutmadın, değil mi? Saat on birde, Ahmet Bey'in odasında.", n: "Guten Morgen, Lena! Du hast die Besprechung heute nicht vergessen, oder? Um elf Uhr, im Büro von Ahmet Bey." },
    { me: true, id: "tr-a2-d08.c1",
      o: ["Günaydın Mert! Hayır, unutmadım. Önce müşteriye bir e-posta göndermem lazım.", "Günaydın Mert! Hayır, unutmadım. Önce müşteriye bir e-posta göndermen lazım.", "Günaydın Mert! Hayır, unutmadım. Önce müşteri bir e-posta göndermem lazım."], a: 0,
      why: { 1: "„göndermen“ heißt „dein Senden“, also „du musst senden“. Lena spricht von sich: „göndermem lazım“ (ich muss senden).", 2: "Der Empfänger braucht den Dativ: „müşteriye“ (dem Kunden). Ohne die Endung fehlt die Beziehung." },
      e: "Notwendigkeit mit „lazım“: Verbstamm + -mA + Possessiv + „lazım“: „gönder-me-m lazım“ = ich muss senden. Der Empfänger steht im Dativ: müşteri**ye**. Unter Kollegen gilt hier „sen“.",
      n: "Guten Morgen, Mert! Nein, habe ich nicht. Vorher muss ich dem Kunden noch eine E-Mail schicken." },
    { s: "Ahmet Bey", g: "m", t: "Saat on bir oldu, herkes burada. Başlayalım. Lena Hanım, müşteriyle yaptığınız görüşme nasıl geçti?", n: "Es ist elf Uhr, alle sind da. Fangen wir an. Frau Lena, wie ist das Gespräch mit dem Kunden gelaufen?" },
    { me: true, id: "tr-a2-d08.c2",
      o: ["İyi geçti, teşekkür ederim. Müşteri teklifimizi beğendi ama fiyat konusunda biraz düşünmek istiyor.", "İyi geçti, sağ ol. Müşteri teklifimizi beğendi ama fiyat konusunda biraz düşünmek istiyor.", "İyi geçti, teşekkür ederim. Müşteri teklifimizi beğendin ama fiyat konusunda biraz düşünmek istiyor."], a: 0,
      why: { 1: "„Sağ ol“ ist die lockere „sen“-Form. Zum Vorgesetzten sagst du „teşekkür ederim“.", 2: "„beğendin“ heißt „du hast gemocht“. Der Kunde ist die 3. Person: „beğendi“ (er hat gemocht)." },
      e: "Dem Chef gegenüber: „teşekkür ederim“. Die 3. Person Singular der -dI-Vergangenheit hat keine Endung: „müşteri beğen-di“. „-mAk istiyor“ = er möchte … (hier: überlegen). Die Frage des Chefs enthält „yaptığınız görüşme“ (das Gespräch, das Sie geführt haben, -DIk-Partizip): hier nur zum Verstehen.",
      n: "Es lief gut, danke. Der Kunde mochte unser Angebot, möchte sich aber wegen des Preises noch etwas Bedenkzeit nehmen." },
    { s: "Ahmet Bey", g: "m", t: "Güzel. O zaman müşteriye bugün bir e-posta yazın ve yeni fiyat listesini ekleyin. Cuma gününe kadar cevap bekliyoruz.", n: "Schön. Dann schreiben Sie dem Kunden heute eine E-Mail und hängen Sie die neue Preisliste an. Bis Freitag erwarten wir eine Antwort." },
    { me: true, id: "tr-a2-d08.c3",
      o: ["Tamam, Ahmet Bey, öğleden önce göndereceğim. Ekte fiyat listesi de olacak.", "Tamam, Ahmet Bey, öğleden önce göndermeyeceğim. Ekte fiyat listesi de olacak.", "Tamam, Ahmet Bey, öğleden önce gönder. Ekte fiyat listesi de olacak."], a: 0,
      why: { 1: "„göndermeyeceğim“ heißt „ich werde nicht senden“. Du sagst dem Chef aber zu, dass du es tust: „göndereceğim“.", 2: "„gönder“ ist ein Befehl („sende!“). Du versprichst es selbst und gibst dem Chef keinen Befehl: „göndereceğim“." },
      e: "Zusage mit dem Futur: gönder + **eceğim** (ich werde senden). „Ekte“ = im Anhang (bei E-Mails). „Öğleden önce“ = vor Mittag.",
      n: "In Ordnung, ich schicke sie vor Mittag. Die Preisliste hänge ich auch an." },
    { s: "Ahmet Bey", g: "m", t: "Çok iyi, teşekkürler. Başka bir sorunuz var mı?", n: "Sehr gut, danke. Haben Sie noch eine Frage?" },
    { me: true, id: "tr-a2-d08.c4",
      o: ["Evet, bir sorum var. Gelecek hafta iki gün izin alabilir miyim?", "Evet, bir sorum var. Gelecek hafta iki gün izin alabilir misiniz?", "Evet, bir sorum var. Gelecek hafta iki günler izin alabilir miyim?"], a: 0,
      why: { 1: "„alabilir misiniz“ heißt „können Sie nehmen“. Du fragst, ob **du** freinehmen darfst: „alabilir miyim?“.", 2: "Nach einer Zahl steht kein Plural: „iki gün“, nicht „iki günler“." },
      e: "Erlaubnis erfragen: „-(y)Abilir miyim?“. Nach Zahlen bleibt das Nomen im Singular: „iki gün“. „İzin almak“ = Urlaub oder frei nehmen.",
      n: "Ja, ich habe eine Frage. Kann ich nächste Woche zwei Tage Urlaub nehmen?" },
    { s: "Ahmet Bey", g: "m", t: "Tabii, e-postayla bildirin lütfen, ben de onaylarım.", n: "Natürlich, teilen Sie es mir bitte per E-Mail mit, ich genehmige es dann." }
  ],
  questions: [
    { id: "tr-a2-d08.1", t: "mc", q: "Was soll Lena nach der Besprechung als Erstes tun?", o: ["Dem Kunden eine E-Mail mit der neuen Preisliste schicken", "Den Bericht der letzten Woche neu schreiben", "Den Kunden anrufen und einen Termin vereinbaren"], a: 0,
      why: { 1: "Von einem Bericht ist keine Rede. Der Chef sagt: „müşteriye … bir e-posta yazın“.", 2: "Angerufen wird nicht. Der Chef will eine E-Mail („e-posta“) mit der Preisliste im Anhang." },
      e: "„Müşteriye bugün bir e-posta yazın ve yeni fiyat listesini ekleyin“ = Schreiben Sie dem Kunden heute eine E-Mail und fügen Sie die neue Preisliste hinzu. Lena sagt zu, das vor Mittag zu tun." },
    { id: "tr-a2-d08.2", t: "gap", q: "Der Chef bittet Lena höflich (siz): „Müşteriye bir e-posta yaz___.“ (Schreiben Sie dem Kunden eine E-Mail.)", a: ["ın", "ınız"],
      wrong: { "in": "Die Vokalharmonie stimmt nicht. „yaz“ hat den hinteren Vokal „a“, also folgt „-ın“ und nicht „-in“.", "sın": "„yazsın“ heißt „er/sie soll schreiben“. Lena wird direkt angesprochen (siz): „yazın“." },
      e: "Höfliche Aufforderung (siz): Verbstamm + **-(y)In**. „yaz“ → „yazın“ (hinterer Vokal a → ı). „-(y)InIz“ („yazınız“) ist noch förmlicher und wird eher schriftlich benutzt. Zu Freunden (sen) wäre es der blanke Stamm „yaz“." },
    { id: "tr-a2-d08.3", t: "match", q: "Ordne die Büro-Wörter zu.", p: [["toplantı", "Besprechung"], ["konu", "Betreff, Thema"], ["ek", "Anhang"], ["izin", "Urlaub, Freistellung"]],
      e: "In einer E-Mail steht der Betreff unter „konu“, Dateien unter „ek“. „Toplantıya katılmak“ = an einer Besprechung teilnehmen. „İzin almak“ = Urlaub nehmen." },
    { id: "tr-a2-d08.4", t: "mc", q: "Sprachmittlung: Deine Mutter versteht kein Türkisch und fragt dich: „Was möchte Lena am Ende von ihrem Chef?“", o: ["Sie möchte nächste Woche zwei Tage freinehmen.", "Sie möchte eine Gehaltserhöhung.", "Sie möchte in ein anderes Büro wechseln."], a: 0,
      why: { 1: "Von Gehalt ist nicht die Rede. Lena fragt nach „iki gün izin“ (zwei Tage Urlaub).", 2: "Ein Bürowechsel wird nicht erwähnt. Lena fragt: „Gelecek hafta iki gün izin alabilir miyim?“" },
      e: "„İzin“ = Urlaub oder Freistellung, „izin almak“ = freinehmen. Der Chef antwortet: Sie soll es per E-Mail mitteilen („e-postayla bildirin“), dann genehmigt er es („onaylarım“)." }
  ] });

K.addDialog('tr-a2-d09', {
  level: 'A2', scene: 'dugun', title: 'Düğün daveti', sub: 'Einladung zur Hochzeit und auf der Feier: Freundin duzen, ihren Vater siezen',
  role: 'Gast', roleG: 'm',
  lines: [
    { s: "Elif", g: "f", t: "Merhaba Can! Sana güzel bir haberim var: Emre'yle evleniyoruz! Gelecek ay düğünümüz var, gelir misin?", n: "Hallo Can! Ich habe tolle Neuigkeiten: Ich heirate Emre! Nächsten Monat feiern wir Hochzeit. Kommst du?" },
    { me: true, id: "tr-a2-d09.c1",
      o: ["Vay, ne güzel! Tebrikler! Tabii ki gelirim, davetin için çok teşekkür ederim.", "Vay, ne güzel! Tebrikler! Tabii ki gelirim, davetin için çok teşekkür edersin.", "Vay, ne güzel! Tebrikler! Tabii ki geldim, davetin için çok teşekkür ederim."], a: 0,
      why: { 1: "„edersin“ heißt „du dankst“. Gemeint ist „ich danke“: „teşekkür ederim“.", 2: "„geldim“ heißt „ich bin gekommen“. Die Hochzeit liegt in der Zukunft: „gelirim“ (ich komme) oder „geleceğim“." },
      e: "Unter Freunden gilt „sen“: davet**in** (deine Einladung). Zusage mit dem Aorist: „gelirim“ = ich komme (gern). „Tebrikler!“ = Glückwunsch!",
      n: "Wie schön! Glückwunsch! Natürlich komme ich, vielen Dank für deine Einladung." },
    { s: "Elif", g: "f", t: "Çok sevindim! Düğün cumartesi akşamı saat yedide, düğün salonunda. İstersen yanında bir arkadaşını da getirebilirsin.", n: "Das freut mich sehr! Die Feier ist Samstagabend um sieben Uhr im Saal. Wenn du magst, kannst du auch einen Freund mitbringen." },
    { me: true, id: "tr-a2-d09.c2",
      o: ["Teşekkürler ama yalnız geleceğim. Ne giymeliyim? Takım elbise şart mı?", "Teşekkürler ama yalnız geleceğim. Ne giymelisin? Takım elbise şart mı?", "Teşekkürler ama yalnız geleceğim. Ne giymeliyim? Takım elbise şartmı?"], a: 0,
      why: { 1: "„giymelisin“ heißt „du musst anziehen“. Du fragst, was **du** anziehen sollst: „giymeliyim“.", 2: "Die Fragepartikel „mi“ wird immer getrennt geschrieben: „şart mı?“. „şartmı“ ist falsch." },
      e: "Sollen mit **-mAlI**: „giy-meli-yim“ = ich soll/muss anziehen. Ja/Nein-Fragen: Wort + getrenntes „mi/mı/mu/mü“ („şart mı?“). Die Partikel richtet sich nach dem letzten Vokal: şart → „mı“.",
      n: "Danke, aber ich komme allein. Was soll ich anziehen? Muss es ein Anzug sein?" },
    { s: "Elif", g: "f", t: "Takım elbise şart değil ama şık giy. Babamla da orada tanışırsın, ona siz demeyi unutma! Cumartesi görüşürüz!", n: "Ein Anzug ist nicht Pflicht, aber zieh dich schick an. Meinen Vater lernst du dort auch kennen, vergiss nicht, ihn zu siezen! Bis Samstag!" },
    { s: "Mehmet Bey", g: "m", t: "Hoş geldin oğlum! Sen Can'sın, değil mi? Elif bize senden çok bahsetti.", n: "Willkommen, mein Junge! Du bist Can, nicht wahr? Elif hat uns viel von dir erzählt." },
    { me: true, id: "tr-a2-d09.c3",
      o: ["Hoş bulduk. Davetiniz için çok teşekkür ederim, Mehmet Bey. Salon çok güzel.", "Hoş bulduk. Davetin için çok teşekkür ederim, Mehmet Bey. Salon çok güzel.", "Hoş geldim. Davetiniz için çok teşekkür ederim, Mehmet Bey. Salon çok güzel."], a: 0,
      why: { 1: "„Davetin“ ist die „sen“-Form. Mehmet Bey ist Elifs Vater und älter, daher „davetiniz“.", 2: "Auf „Hoş geldin“ antwortet man „Hoş bulduk“. „Hoş geldim“ wäre eine zweite Begrüßung und keine Antwort." },
      e: "Begrüßung: „Hoş geldin(iz)“ → Antwort „Hoş bulduk“. Mehmet Bey darf als Älterer „sen“ sagen, du als Gast gehst bei „siz“ (davet**iniz**) und nennst den Namen mit „Bey“. Statt „Mehmet Bey“ hört man oft auch „Mehmet Amca“ (älterer Mann, wie „Onkel“).",
      n: "Danke, schön hier zu sein. Vielen Dank für Ihre Einladung, Mehmet Bey. Der Saal ist sehr schön." },
    { s: "Mehmet Bey", g: "m", t: "Biz de çok sevindik. Elif ile Emre birazdan pasta kesecek. Sen şu masaya geç, yemekler de gelir.", n: "Wir freuen uns auch sehr. Elif und Emre schneiden gleich die Torte an. Setz dich an diesen Tisch, das Essen kommt auch gleich." },
    { me: true, id: "tr-a2-d09.c4",
      o: ["Bir zarf getirdim. Nereye bırakabilirim?", "Bir zarf getirdi. Nereye bırakabilirim?", "Bir zarf getirdim. Nereye bırakabilirsiniz?"], a: 0,
      why: { 1: "„getirdi“ heißt „er/sie hat gebracht“. Du sprichst von dir: „getirdim“ (ich habe gebracht).", 2: "„bırakabilirsiniz“ heißt „Sie können hinlegen“. Du fragst, wohin **du** ihn legen kannst: „bırakabilirim“." },
      e: "Auf Hochzeiten bringt man oft einen Umschlag („zarf“) mit Geld oder ein Geschenk mit. „Nereye bırakabilirim?“ = Wohin kann ich ihn legen? Möglichkeit in der 1. Person: -(y)Abilir + im.",
      n: "Ich habe einen Umschlag mitgebracht. Wohin kann ich ihn legen?" },
    { s: "Mehmet Bey", g: "m", t: "Sağ ol evladım. Şu masadaki kutuya atabilirsin. Afiyet olsun, eğlen!", n: "Danke, mein Kind. Du kannst ihn in die Kiste auf dem Tisch dort werfen. Guten Appetit, amüsier dich!" }
  ],
  questions: [
    { id: "tr-a2-d09.1", t: "mc", q: "Was soll Can zur Hochzeit anziehen?", o: ["Es muss kein Anzug sein, aber schick.", "Unbedingt einen Anzug.", "Etwas Lockeres wie Jeans und T-Shirt."], a: 0,
      why: { 1: "Elif sagt: „Takım elbise şart değil“. Ein Anzug ist also keine Pflicht.", 2: "Locker ist nicht gewünscht. Elif sagt: „şık giy“ (zieh dich schick an)." },
      e: "„Şart değil“ = ist nicht Pflicht. „Şık giy“ = zieh dich schick an (sen-Aufforderung, blanker Verbstamm)." },
    { id: "tr-a2-d09.2", t: "gap", q: "Can zu Mehmet Bey (siz): „Davet___ için çok teşekkür ederim.“ (Ihre Einladung)", a: ["iniz"],
      wrong: { "ınız": "Die Vokalharmonie stimmt nicht. „davet“ hat zuletzt den vorderen Vokal „e“, also folgt „-iniz“.", "in": "„davetin“ heißt „deine Einladung“ (sen). Mehmet Bey ist älter, also „siz“: „davetiniz“." },
      e: "Possessiv der 2. Person Plural (siz): nach Konsonant **-(I)nIz**. „davet“ (letzter Vokal e) → „davet**iniz**“. „Davetin“ wäre die Freundesform (sen)." },
    { id: "tr-a2-d09.3", t: "match", q: "Ordne die Hochzeitswörter zu.", p: [["düğün", "Hochzeitsfeier"], ["davetiye", "Einladungskarte"], ["gelin", "Braut"], ["damat", "Bräutigam"]],
      e: "„Düğün“ ist die Feier, „davetiye“ die Karte dazu. „Gelin“ und „damat“ sind Braut und Bräutigam. Zum Brautpaar sagt man „Tebrikler!“ oder „Mutluluklar!“." },
    { id: "tr-a2-d09.4", t: "order", q: "Bilde die Frage: „Kommst du zu unserer Hochzeit?“", w: ["gelir", "Düğünümüze", "misin"], a: ["Düğünümüze gelir misin"],
      e: "„Düğünümüze“ (zu unserer Hochzeit, Dativ) steht vorn. Danach das Verb im Aorist „gelir“ und die getrennte Partikel „misin“. Das Verb mit der Fragepartikel steht am Satzende." },
    { id: "tr-a2-d09.5", t: "mc", q: "Sprachmittlung: Deine Kollegin versteht kein Türkisch und fragt dich: „Was hat Mehmet Bey zu dem Umschlag gesagt?“", o: ["Ich soll ihn in die Kiste auf dem Tisch legen.", "Ich soll ihn dem Brautpaar direkt geben.", "Ich soll ihn zu Hause lassen."], a: 0,
      why: { 1: "Er sagt: „Şu masadaki kutuya atabilirsin“, also in die Kiste, nicht direkt ans Brautpaar.", 2: "Er verbietet nichts. Er zeigt Can, wohin der Umschlag kommt: in die Kiste („kutu“)." },
      e: "„Kutuya atabilirsin“ = du kannst (ihn) in die Kiste werfen. „-(y)Abilirsin“ ist hier die Erlaubnis in der „sen“-Form. Beim Sprachmitteln gibst du die Handlung wieder, nicht jedes Wort." }
  ] });

K.addDialog('tr-a2-d10', {
  level: 'A2', scene: 'aile', title: 'Aileyle telefonda', sub: 'Mit der Mutter telefonieren: Alltag erzählen, Bayram planen (in der Familie duzt man)',
  role: 'Tochter', roleG: 'f',
  lines: [
    { s: "Anne", g: "f", t: "Alo, kızım! Sesini duyduğuma çok sevindim. Nasılsın? Yemek yedin mi?", n: "Hallo, mein Schatz! Ich freue mich so, deine Stimme zu hören. Wie geht es dir? Hast du schon gegessen?" },
    { me: true, id: "tr-a2-d10.c1",
      o: ["Merhaba anneciğim! İyiyim, yemek yedim. Sen nasılsın?", "Merhaba anneciğim! İyiyim, yemek yedin. Sen nasılsın?"], a: 0,
      why: { 1: "„yedin“ heißt „du hast gegessen“. Die Mutter hat gefragt, ob **du** gegessen hast. Du antwortest über dich: „yedim“ (ich habe gegessen)." },
      e: "Frage und Antwort haben verschiedene Personen: „Yemek yedin mi?“ (hast du gegessen?) → „Yedim“ (ich habe). Die Endung -dI + **m** = 1. Person Singular.",
      n: "Hallo, Mama! Mir geht es gut, ich habe gegessen. Und dir, wie geht es dir?" },
    { s: "Anne", g: "f", t: "Ben de iyiyim. Orada hava nasıl? Soğuk mu? Kalın giy, hasta olma!", n: "Mir geht es auch gut. Wie ist das Wetter dort? Ist es kalt? Zieh dich warm an, werde nicht krank!" },
    { me: true, id: "tr-a2-d10.c2",
      o: ["Biraz soğuk ama kalın giyiniyorum, merak etme. Hafta sonu arkadaşlarla yürüyüşe gideceğiz.", "Biraz soğuk ama kalın giyiniyorum, merak etmem. Hafta sonu arkadaşlarla yürüyüşe gideceğiz.", "Biraz soğuk ama kalın giyiniyorsun, merak etme. Hafta sonu arkadaşlarla yürüyüşe gideceğiz."], a: 0,
      why: { 1: "„merak etmem“ heißt „ich mache mir keine Sorgen“. Du willst die Mutter beruhigen: „merak etme“ (mach dir keine Sorgen).", 2: "„giyiniyorsun“ heißt „du ziehst dich an“. Du sprichst über dich: „giyiniyorum“ (ich ziehe mich an)." },
      e: "Verneinte Aufforderung (sen): Verbstamm + **-mA**: „merak etme“, „hasta olma“. Die Personenendung des Präsens: -(I)yor + **um** (ich), -sun (du).",
      n: "Es ist etwas kalt, aber ich ziehe mich warm an, mach dir keine Sorgen. Am Wochenende gehen wir mit Freunden spazieren." },
    { s: "Anne", g: "f", t: "Babaannen de seni soruyor. Yeni evden memnun musun? Bir de bayramda gelebilecek misin?", n: "Deine Oma fragt auch nach dir. Bist du mit der neuen Wohnung zufrieden? Und kannst du zum Bayram kommen?" },
    { me: true, id: "tr-a2-d10.c3",
      o: ["Evet, ev çok güzel. Bayramda gelebileceğim, biletimi de aldım.", "Evet, ev çok güzel. Bayramda gelemeyeceğim, biletimi de aldım.", "Evet, ev çok güzel. Bayramda geleceksin, biletimi de aldım."], a: 0,
      why: { 1: "„gelemeyeceğim“ heißt „ich werde nicht kommen können“. Das passt nicht dazu, dass du schon ein Ticket gekauft hast.", 2: "„geleceksin“ heißt „du wirst kommen“. Du sprichst von dir: „geleceğim“ oder „gelebileceğim“." },
      e: "Möglichkeit in der Zukunft: Verbstamm + **-(y)Abil** + -(y)AcAk + Personenendung: „gel-ebil-ecek-im“ → „gelebileceğim“ (k wird vor Vokal zu ğ). Verneint: „gelemeyeceğim“.",
      n: "Ja, die Wohnung ist sehr schön. Zum Bayram kann ich kommen, mein Ticket habe ich auch schon gekauft." },
    { s: "Anne", g: "f", t: "Çok sevindim! Baban da çok mutlu olacak. Seni havaalanından alırız. Uçuş saatini bana mesaj atar mısın?", n: "Das freut mich so! Dein Vater wird auch sehr glücklich sein. Wir holen dich vom Flughafen ab. Schickst du mir die Flugzeit per Nachricht?" },
    { me: true, id: "tr-a2-d10.c4",
      o: ["Tabii anne, akşam mesaj atarım. Sana bir şey getireyim mi?", "Tabii anne, akşam mesaj atarım. Sana bir şey getirdim mi?", "Tabii anne, akşam mesaj atarım. Sana bir şey getirsin mi?"], a: 0,
      why: { 1: "„getirdim mi“ fragt „habe ich mitgebracht?“, also Vergangenheit. Du möchtest anbieten, etwas mitzubringen: „getireyim mi?“.", 2: "„getirsin mi“ heißt „soll er/sie mitbringen?“. Du bietest an, es selbst zu tun: „getireyim mi?“." },
      e: "Angebot in der 1. Person: **-(y)AyIm mI?** = Soll ich …? („getir-eyim mi?“). „Mesaj atmak“ = eine Nachricht schicken. „Atarım“ = ich schicke (Zusage im Aorist).",
      n: "Natürlich, Mama, ich schicke dir heute Abend eine Nachricht. Soll ich dir etwas mitbringen?" },
    { s: "Anne", g: "f", t: "Yok kızım, sen sağ salim gel yeter. Kendine iyi bak, seni çok seviyoruz!", n: "Nein, mein Schatz, komm du nur heil und gesund an. Pass gut auf dich auf, wir haben dich sehr lieb!" }
  ],
  questions: [
    { id: "tr-a2-d10.1", t: "mc", q: "Was hat die Tochter für den Bayram schon erledigt?", o: ["Sie hat das Ticket gekauft.", "Sie hat Geschenke besorgt.", "Sie hat ihre Oma angerufen."], a: 0,
      why: { 1: "Von Geschenken ist nicht die Rede. Die Mutter lehnt sogar ab, dass sie etwas mitbringt.", 2: "Die Oma fragt nur über die Mutter nach ihr („Babaannen de seni soruyor“). Angerufen hat die Tochter sie nicht." },
      e: "„Biletimi de aldım“ = Mein Ticket habe ich auch schon gekauft. „-dI“ + „-m“: die erledigte Handlung in der 1. Person." },
    { id: "tr-a2-d10.2", t: "gap", q: "Die Mutter sagt: „Kalın giy, hasta ___!“ (Werde nicht krank!)", a: ["olma"],
      wrong: { "olmaz": "„olmaz“ heißt „es geht nicht“ oder „wird nicht“. Eine Warnung an dich ist die verneinte Aufforderung: „olma“.", "olmayın": "„-mayın“ ist die verneinte Aufforderung an mehrere Personen oder an eine gesiezte Person. Die Mutter duzt dich: „olma“." },
      e: "Verneinte Aufforderung in der „sen“-Form: Verbstamm + **-mA**. „olmak“ → „olma“ (werde nicht), „merak etmek“ → „merak etme“." },
    { id: "tr-a2-d10.3", t: "match", q: "Ordne die Verwandten zu.", p: [["babaanne", "Oma väterlicherseits"], ["anneanne", "Oma mütterlicherseits"], ["dayı", "Onkel (Bruder der Mutter)"], ["amca", "Onkel (Bruder des Vaters)"]],
      e: "Das Türkische unterscheidet die Seite der Familie. „Baba“ + „anne“ = Mutter des Vaters („babaanne“), „anne“ + „anne“ = Mutter der Mutter („anneanne“). Onkel heißen „dayı“ (mütterlicherseits) und „amca“ (väterlicherseits)." },
    { id: "tr-a2-d10.4", t: "mc", q: "Sprachmittlung: Dein Freund versteht kein Türkisch und fragt: „Was soll sie ihrer Mutter am Abend schicken?“", o: ["Die Flugzeit per Nachricht.", "Ein Foto von der Wohnung.", "Ihre neue Adresse."], a: 0,
      why: { 1: "Ein Foto wird nicht erwähnt. Die Mutter möchte „uçuş saati“ (Flugzeit) wissen.", 2: "Von der Adresse ist keine Rede. Die Mutter möchte die Flugzeit, damit sie die Tochter abholen kann." },
      e: "„Uçuş saatini bana mesaj atar mısın?“ = Schickst du mir die Flugzeit per Nachricht? „Mesaj atmak“ ist umgangssprachlich für eine Nachricht schicken. Die Tochter sagt zu: „akşam mesaj atarım“." }
  ] });

})(window.KOPRU);
